let logger = $("#logger").DataTable({
  scrollX: true,
  ajax: JSONLogger,
  columnDefs: [
    {
      searcable: false,
      orderable: false,
      targets: 0,
    },
  ],
  order: [[1, "desc"]],
  columns: [
    {
      data: "no",
    },
    {
      data: "no",
    },
    {
      data: "nohp",
    },
    {
      data: "template",
    },
    {
      data: "datetime",
    },
    {
      data: "myapp",
    },
    {
      data: "status",
    },
    {
      data: "message",
    },
  ],
});

$(function () {
  // turn the element to select2 select styl
  $("#groupwa").on("change", function () {
    var data = $("#groupwa option:selected").val();
    vnotelp(data);
  });
  $("#message").on("change", function () {
    var data = $("#message option:selected").text();
    //document.getElementById("myTextarea").value
    vmessage(data);
  });
  $("#myapp").on("change", function () {
    var data = $("#myapp option:selected").val();
    //document.getElementById("myTextarea").value
    vapi(data);
  });
  $("#template").on("change", function () {
    var data = $("#template option:selected").text();
    let arr = data.split("::");
    $('[name="type"]').val(arr[3]);
    $('[name="imageurl"]').val(arr[4]);

    //document.getElementById("myTextarea").value
  });
});
function vmessage(a) {
  $.ajax({
    url: JSONmessagebyno,
    type: "get",
    dataType: "json",
    data: {
      no: a,
    },
    success: (a) => {
      $('[name="vmessage"]').val(a.message);
    },
    error: (a) => {
      console.log(a);
    },
  });
}
function vapi(a) {
  let url2 = readapiserver + "?no=" + a + "";
  $("#apiserver").DataTable({
    bDestroy: true,
    responsive: true,
    scrollX: true,
    ajax: url2,
    columnDefs: [
      {
        searcable: false,
        orderable: false,
        targets: 0,
      },
    ],
    order: [[1, "asc"]],
    columns: [
      {
        data: "no",
      },
      {
        data: "no",
      },
      {
        data: "appkey",
      },
      {
        data: "authkey",
      },
      {
        data: "vendor",
      },
    ],
  });
}
function vnotelp(a) {
  let url = readgroupwa + "?no=" + a + "";
  $("#notelp").DataTable({
    bDestroy: true,
    responsive: true,
    scrollX: true,
    ajax: url,
    columnDefs: [
      {
        searcable: false,
        orderable: false,
        targets: 0,
      },
    ],
    order: [[1, "asc"]],
    columns: [
      {
        data: "no",
      },
      {
        data: "no",
      },
      {
        data: "nama",
      },
      {
        data: "nohp",
      },
      {
        data: "namagroup",
      },
    ],
  });
}
$("#myapp").select2({
  placeholder: "Pilih API Server",
  ajax: {
    url: JSONmyapp,
    type: "get",
    dataType: "json",
  },
});
$("#message").select2({
  placeholder: "Pilih No Message",
  ajax: {
    url: JSONmessage,
    type: "get",
    dataType: "json",
  },
});
$("#groupwa").select2({
  placeholder: "Pilih Groupwa",
  ajax: {
    url: JSONGroupwa,
    type: "get",
    dataType: "json",
  },
});
$("#template").select2({
  placeholder: "Pilih Template",
  ajax: {
    url: JSONTemplate,
    type: "get",
    dataType: "json",
  },
});
function reloadTable() {
  logger.reloadTable;
}
function addData() {
  $.ajax({
    xhr: function () {
      var xhr = new window.XMLHttpRequest();

      // Upload progress
      xhr.upload.addEventListener(
        "progress",
        function (evt) {
          if (evt.lengthComputable) {
            var percentComplete = evt.loaded / evt.total;
            //Do something with upload progress
            console.log(percentComplete);
          }
        },
        false
      );

      // Download progress
      xhr.addEventListener(
        "progress",
        function (evt) {
          if (evt.lengthComputable) {
            var percentComplete = evt.loaded / evt.total;
            // Do something with download progress
            console.log(percentComplete);
          }
        },
        false
      );

      return xhr;
    },
    url: sendUrl,
    type: "get",
    dataType: "json",
    data: $("#form").serialize(),
    success: (a) => {
      Swal.fire("Sukses", "Sukses Menambahkan Data", "success");
    },
    error: (a) => {
      Swal.fire("Error", "Ada yang error", "error");
    },
  });
}
$("#form").validate({
  submitHandler: () => {
    addData();
  },
});
